        press: true, extCapital: 0, valueCeded: 0, minCash: 8400000, dual: 1, months: 0, flags: {},
        monthlyAdRevenue: 2200000, monthlyRevenue: 3500000, monthlyDigitalRevenue: 0, digitalSubscribers: 0,
