      if (!(decisions.strategy >= 1 && decisions.strategy <= 4)) { notify(this._t('strategy_warning')); return false; }
      if (!isFinite(decisions.investment) || decisions.investment < r.investMin || decisions.investment > r.investMax) {
        notify(this._t('investment_warning') + ' (' + this._money(r.investMin) + ' – ' + this._money(r.investMax) + ')');
