    _revenue(s) { return s.ad + s.psub + s.oth + s.members * s.price + s.digOther; }
    _costs(s) { return s.employees * C.STAFF_COST + s.printCost + s.otherCost * (0.15 + 0.85 * s.employees / 480) + s.digOpex; }
    _digital(s) { return Math.round(s.members * s.price + s.digOther); }

    _playRound(state) {
      var s = JSON.parse(JSON.stringify(state.domainState || {}));
      if (!s.flags) s = Object.assign(this._freshState(), s);
      state.domainState = s;
      var d = state.decisions || {};
      var r = state.currentPeriod;
      var f = s.flags, st = +d.strategy, inv = +d.investment, res = +d.resource;
      var cashIn = s.cash, one = 0, ev = {};
      if (r === 1) {
        s.ad = 2200000 * 0.70 * (1 - Math.max(0, res - 80) / 20 * 0.05);
        var bq = 1 - Math.exp(-inv / 150000);
        var tq = Math.min(1, 0.3 + 0.8 * res / 100);
        s.diagQ = C.FOCUS_Q[st] * (0.55 + 0.45 * bq) * tq;
        if (st === 2) { s.otherCost = 500000 * 0.88; s.printCost = 1000000 * 0.94; f.costLens = 1; }
        if (res <= 40) f.partTime = 1;
        if (res > 80) ev.printNeglect = 1;
        one = inv; s.months = 3;
      } else if (r === 2) {
        s.model = st;
        s.ad = 2200000 * 0.55; s.psub = 900000 * 0.95;
        var invQ = 1 - Math.exp(-inv / 500000);
        var fitS = Math.pow(Math.min(1, res / C.NEED[st]), 0.8);
        s.K = invQ * fitS * C.FIT[st] * (0.3 + 0.7 * s.diagQ);
        if (invQ * fitS < 0.35) f.starved = 1;
        if (st === 2) { s.ad *= 0.6; s.psub *= 0.6; s.printCost *= 0.7; s.brand -= 12; f.closedFlagship = 1; s.price = 16; }
        if (st === 4) { s.brand -= 6; f.saas = 1; }
        s.members = C.MEMBER_POT[st] * s.K * 0.12;
        s.digOther = C.OTHER_POT[st] * s.K * 0.25;
        s.digOpex = 40000 + (st === 4 ? 0.35 * s.digOther : 0);
        one = inv + res * 2500; s.months = 3;
      } else if (r === 3) {
        var L = Math.max(0, Math.min(Math.round(res), s.employees - 50));
        var legal = L * C.LEGAL_SEV, g = 0, sev = legal;
        if (st === 1 || st === 2) { sev = Math.max(inv, legal); g = L > 0 ? clamp((inv - legal) / (L * C.GEN_SEV), 0, 1) : 1; }
        s.employees -= L;
        s.brand -= L / 20 * (1 - 0.6 * g);
        if (L >= 150 && g < 0.15) f.harshLayoffs = 1;
        if (L >= 100) s.K *= (0.85 + 0.15 * g);
        var dual = 1;
        s.ad = 2200000 * 0.35; s.psub = (s.model === 2 ? 0.6 : 1) * 900000 * 0.8; s.oth = 400000 * 0.6;
        if (st === 1) {
          s.print = 'closed'; s.ad = 0; s.psub = 0; s.oth = 400000 * 0.3; s.printCost = 0;
          s.digOther += 150000 * s.K; s.members += 7000 * s.K; s.brand -= 3;
          if (s.press) { one -= 4000000; s.press = false; ev.pressSold = 1; }
          if (s.employees > 250) f.closedButFat = 1;
        } else {
          s.print = 'reduced'; s.printCost = Math.min(s.printCost, 1000000 * 0.55); s.ad *= 0.8; s.psub *= 0.6;
          dual = 0.7; f.dual = 1;
          if (st === 3) {
            var traction = clamp(this._digital(s) / 120000, 0, 1), cap = 3000000 * traction;
            var raised = inv <= cap ? inv : cap * 0.5;
            if (inv > cap) f.overAsk = 1;
            one -= raised; s.extCapital += raised; s.K = Math.min(1, s.K + 0.08); f.investor = 1; ev.raised = raised;
          }
          if (st === 4) {
            var cert = clamp(inv / 2000000, 0, 1);
            s.printCost *= (1 - 0.5 * cert); s.otherCost *= (1 - 0.3 * cert);
            s.brand -= 12; s.K *= 0.85; s.valueCeded += inv; f.sold = 1;
          }
        }
        s.dual = dual;
        var minStaff = C.NEED[s.model] + 15;
        if (s.employees < minStaff) { s.K *= Math.pow(s.employees / minStaff, 1.5); f.hollowed = 1; }
        s.members += C.MEMBER_POT[s.model] * s.K * 0.25 * dual;
        s.digOther = Math.max(s.digOther, C.OTHER_POT[s.model] * s.K * 0.55 * dual);
        s.digOpex = 60000 + (s.model === 4 ? 0.35 * s.digOther : 0);
        one += sev; s.months = 6; ev.layoffs = L; ev.severance = sev; ev.generosity = g;
      } else if (r === 4) {
        var p = res, mk = inv;
        if (s.print === 'reduced') { s.ad = 2200000 * 0.25 * 0.8; s.psub *= 0.75; }
        var ref = s.model === 2 ? 16 : 9;
        if (p > ref) { s.members *= Math.pow(ref / p, 0.6); f.priceShock = 1; }
        s.price = p;
        var acq = { 1: 1.3, 2: 1.0, 3: 0.7, 4: 0.8 }[st];
        var churnAdd = { 1: 0.015, 2: 0, 3: -0.005, 4: 0.01 }[st];
        var extra = { 1: 80000, 2: 0, 3: -60000, 4: 0 }[st];
        if (st === 4) { s.K *= 0.6; s.brand -= 4; one += 400000; f.repivot = 1; }
        var cac = 35 * (1 + Math.pow(mk / 200000, 1.5));
        var priceF = Math.pow(ref / p, 1.2);
        var churn = clamp(0.035 + (p > ref ? 0.004 * (p - ref) : 0.006 * (ref - p)) + 0.01 * mk / 250000 + churnAdd, 0.02, 0.15);
        var newM = 0;
