      s.totalRevenueHistory = (s.totalRevenueHistory || []).concat([s.monthlyRevenue]);
      s.cashHistory = (s.cashHistory || []).concat([s.cash]);
      s.digitalRevenueHistory = (s.digitalRevenueHistory || []).concat([s.monthlyDigitalRevenue]);
      s.adRevenueHistory = (s.adRevenueHistory || []).concat([s.monthlyAdRevenue]);
