      return {
        period: r, choice: r * 10 + st, investment: inv, resource: res,
        adRevenue: s.monthlyAdRevenue, totalRevenue: s.monthlyRevenue, digitalRevenue: s.monthlyDigitalRevenue,
        monthlyResult: Math.round(s.monthlyResult), totalSubscribers: s.digitalSubscribers, employees: s.employees,
        brandReputation: s.brandReputation, cash: s.cash,
