    }

    _computeScore(s) {
      s = s || {};
      var cash = s.cash || 0, ext = s.extCapital || 0, ceded = s.valueCeded || 0;
      var cashAdj = cash - ceded - 0.5 * ext;
      var cashPts = 25 * clamp(cashAdj / 4000000, 0, 1);
      var op = (s.ad != null) ? (this._revenue(s) - this._costs(s)) : 0;
      if (op < 0) cashPts *= clamp((Math.max(0, cash) / -op) / 12, 0, 1);
      var digPts = 30 * clamp(((s.members || 0) * (s.price || 0) + (s.digOther || 0)) * 12 / 4000000, 0, 1);
      var subPts = 25 * clamp((s.members || 0) / 20000, 0, 1);
      var brandPts = 20 * clamp(((s.brand != null ? s.brand : 85) - 40) / 40, 0, 1);
      var total = cashPts + digPts + subPts + brandPts;
      if (s.minCash != null && s.minCash < 0) total = Math.min(total, 30);
      total = clamp(Math.round(total), 0, 100);
      var tier = 'atrisk';
      for (var i = 0; i < C.TIERS.length; i++) { if (total >= C.TIERS[i][0]) { tier = C.TIERS[i][1]; break; } }
      return { total: total, tier: tier, cashPts: Math.round(cashPts), digPts: Math.round(digPts), subPts: Math.round(subPts), brandPts: Math.round(brandPts) };
    }

