        var self = this, cashH = ds.cashHistory || [], adH = ds.adRevenueHistory || [], digH = ds.digitalRevenueHistory || [];
        var rc = document.getElementById('revenueChart'), cc = document.getElementById('cashChart');
        var rtxt = this._t('chart_revenue_alt') + ': ' + (adH.length ? adH.map(function (v, i) { return 'R' + (i + 1) + ' ' + self._money(v) + ' / ' + self._money(digH[i] || 0); }).join('; ') : this._t('chart_empty'));
        var ctxt = this._t('chart_cash_alt') + ': ' + (cashH.length ? cashH.map(function (v, i) { return 'R' + (i + 1) + ' ' + self._money(v); }).join('; ') : this._t('chart_empty'));
        if (rc) { rc.setAttribute('role', 'img'); rc.setAttribute('aria-label', rtxt); }
        if (cc) { cc.setAttribute('role', 'img'); cc.setAttribute('aria-label', ctxt); }
      } catch (e) {}
