    _finalState(history) {
      var ds = null;
      try { ds = window.mySimulation.state.domainState; } catch (e) {}
      if ((!ds || !ds.roundLog) && history && history.length) {
        var last = history[history.length - 1] || {};
        ds = last.domainState || (last.results && last.results.domainState) || ds;
      }
      return ds || this._freshState();
    }

    _mistakes(ds) {
      var f = (ds && ds.flags) || {};
      return C.MISTAKE_ORDER.filter(function (k) { return f[k]; });
    }

    getPerformanceSummary(history) {
      if (!history || !history.length) return {};
      var ds = this._finalState(history);
      var sc = this._computeScore(ds);
      var mistakes = this._mistakes(ds);
      var self = this;
      var insights = mistakes.slice(0, 4).map(function (k) { return self._t('ins_' + k); });
      if (insights.length < 3) {
        if (!(ds.flags || {}).costLens && !(ds.flags || {}).partTime) insights.push(this._t('ins_good_diag'));
        if (insights.length < 3 && !(ds.flags || {}).starved && ds.model) insights.push(this._t('ins_good_model_' + ds.model));
        if (insights.length < 3 && (ds.flags || {}).dual !== 1 && ds.print === 'closed') insights.push(this._t('ins_good_focus'));
        if (insights.length < 3) insights.push(this._t('ins_good_exec'));
      }
      return {
        score: sc.total, overallScore: sc.total, totalScore: sc.total, composite: sc.total,
        performance: sc.tier, performanceKey: 'tier_' + sc.tier, performanceLabel: this._t('tier_' + sc.tier),
        finalCash: ds.cash, annualDigitalRevenue: (ds.monthlyDigitalRevenue || 0) * 12, totalSubscribers: ds.digitalSubscribers,
        brandReputation: ds.brandReputation, monthlyResult: Math.round(ds.monthlyResult || 0),
        parts: { cash: sc.cashPts, digital: sc.digPts, members: sc.subPts, brand: sc.brandPts },
        mistakes: mistakes, turningPoint: mistakes.length ? 'tp_' + mistakes[0] : 'tp_none',
        insights: insights
      };
    }

    formatCompletionMessage(summary) {
      summary = summary || {};
      var self = this, t = function (k) { return self._t(k); };
      var esc = function (x) { return String(x == null ? '' : x).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); };
      var p = summary.parts || {};
      var kpi = function (label, value) { return '<div class="modelo-cm-kpi"><span class="modelo-cm-kpi-label">' + esc(label) + '</span><span class="modelo-cm-kpi-value">' + esc(value) + '</span></div>'; };
      var h = '<div class="modelo-cm" role="region" aria-label="' + esc(t('cm_title')) + '">';
      h += '<h3 class="modelo-cm-title">' + esc(t('cm_title')) + '</h3>';
      h += '<p class="modelo-cm-score"><strong>' + esc(summary.score != null ? summary.score : 0) + '/100</strong> — ' + esc(t('tier_' + (summary.performance || 'atrisk'))) + '</p>';
      h += '<div class="modelo-cm-kpis">' +
        kpi(t('cash_label'), this._money(summary.finalCash || 0)) +
        kpi(t('cm_annual_digital'), this._money(summary.annualDigitalRevenue || 0)) +
        kpi(t('subscribers_label'), this._num(summary.totalSubscribers || 0)) +
        kpi(t('brand_label'), (summary.brandReputation || 0) + '/100') +
        kpi(t('cm_monthly_result'), this._money(summary.monthlyResult || 0)) + '</div>';
      h += '<p class="modelo-cm-parts">' + esc(t('cm_parts')) + ': ' + esc(t('cm_part_cash')) + ' ' + (p.cash || 0) + '/25 · ' + esc(t('cm_part_digital')) + ' ' + (p.digital || 0) + '/30 · ' + esc(t('cm_part_members')) + ' ' + (p.members || 0) + '/25 · ' + esc(t('cm_part_brand')) + ' ' + (p.brand || 0) + '/20</p>';
      h += '<h4>' + esc(t('cm_turning')) + '</h4><p>' + esc(t(summary.turningPoint || 'tp_none')) + '</p>';
      h += '<h4>' + esc(t('cm_insights')) + '</h4><ul>' + (summary.insights || []).map(function (x) { return '<li>' + esc(x) + '</li>'; }).join('') + '</ul>';
