      return h;
    }

    getHint(state, results) {
      var ds = (state && state.domainState) || {};
      var log = ds.roundLog || [], last = log[log.length - 1];
      if (!last) return null;
      var f = ds.flags || {};
      if (f.insolvent && last.cash < 0) return this._t('hint_insolvent');
      if (last.r === 1) return this._t(f.costLens ? 'hint_r1_cost' : (f.partTime ? 'hint_r1_parttime' : 'hint_r1'));
      if (last.r === 2) return this._t(f.starved ? 'hint_r2_starved' : 'hint_r2');
      if (last.r === 3) return this._t(f.dual ? 'hint_r3_dual' : (f.harshLayoffs ? 'hint_r3_harsh' : 'hint_r3'));
      return null;
    }

