      set('resourceLabel', es ? round.resourceLabelEs : round.resourceLabelEn);
      var sel = document.getElementById('strategySelect');
      if (sel) {
        var keep = keepValues ? sel.value : '';
        var sig = idx + '|' + lang;
        if (sel.getAttribute('data-modelo-round') !== sig) {
          var sameRound = keepValues && sel.getAttribute('data-modelo-round') && sel.getAttribute('data-modelo-round').split('|')[0] === String(idx);
          if (sameRound) {
            for (var j = 0; j < sel.options.length; j++) {
              var o = sel.options[j], ro = round.options.filter(function (x) { return String(x.value) === o.value; })[0];
              if (ro) o.textContent = es ? ro.es : ro.en;
            }
          } else {
            sel.innerHTML = '';
            for (var i = 0; i < round.options.length; i++) {
              var opt = document.createElement('option');
              opt.value = round.options[i].value;
              opt.textContent = es ? round.options[i].es : round.options[i].en;
              sel.appendChild(opt);
            }
            if (keep) sel.value = keep;
          }
          sel.setAttribute('data-modelo-round', sig);
        }
      }
      var invInput = document.getElementById('investmentInput');
      if (invInput) {
        invInput.min = round.investMin; invInput.max = round.investMax; invInput.step = round.investStep;
        if (!keepValues) invInput.value = round.investDefault;
      }
      set('investmentHint', es ? round.investHintEs : round.investHintEn);
      var resInput = document.getElementById('resourceInput');
      if (resInput) {
        resInput.min = round.resourceMin; resInput.max = round.resourceMax; resInput.step = round.resourceStep;
        if (!keepValues) resInput.value = round.resourceDefault;
      }
      set('resourceHint', es ? round.resourceHintEs : round.resourceHintEn);
      try { if (state && state.domainState) this._chartAlt(state.domainState); } catch (e) {}
    }
  }
